let micWaveStream=null,micWaveCtx=null,micWaveRaf=null,speakWaveRaf=null,currentNovaState='ready';
function canvasEls(ids){return ids.map(id=>document.getElementById(id)).filter(Boolean);}
function drawWave(canvases,level=0.15,phase=0){for(const c of canvases){const ctx=c.getContext&&c.getContext('2d');if(!ctx)continue;const w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#0b1020';ctx.fillRect(0,0,w,h);ctx.lineWidth=2;ctx.strokeStyle='#60a5fa';ctx.beginPath();for(let x=0;x<w;x++){const y=h/2+Math.sin((x/18)+phase)*(4+level*h*.35)+Math.sin((x/7)+phase*1.7)*(1+level*h*.08);if(x===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.stroke();}}
function setNovaOrb(state,label,transcript){currentNovaState=state||currentNovaState||'ready';const orb=document.getElementById('novaOrb');if(orb){orb.className='novaOrb '+currentNovaState;orb.textContent=currentNovaState==='listening'?'👂':currentNovaState==='detected'?'✨':currentNovaState==='speaking'?'🔊':currentNovaState==='thinking'||currentNovaState==='working'?'🧠':'🤖';}const title=document.getElementById('novaOrbTitle');if(title&&label)title.textContent=label;const tr=document.getElementById('novaOrbTranscript');if(tr&&transcript)tr.textContent=transcript;}
async function startMicWave(){try{stopMicWave(false);if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia)return;micWaveStream=await navigator.mediaDevices.getUserMedia(voiceAudioConstraint());const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)return;micWaveCtx=new Ctx();const src=micWaveCtx.createMediaStreamSource(micWaveStream);const analyser=micWaveCtx.createAnalyser();analyser.fftSize=256;src.connect(analyser);const data=new Uint8Array(analyser.frequencyBinCount);let phase=0;function tick(){analyser.getByteTimeDomainData(data);let sum=0;for(const v of data){const n=(v-128)/128;sum+=n*n;}const level=Math.min(1,Math.sqrt(sum/data.length)*2.2);drawWave(canvasEls(['voiceWaveCanvas','rightVoiceWaveCanvas']),level,phase+=0.25);micWaveRaf=requestAnimationFrame(tick);}tick();}catch(e){drawWave(canvasEls(['voiceWaveCanvas','rightVoiceWaveCanvas']),0.1,Date.now()/400);}}
function stopMicWave(clear=true){try{if(micWaveRaf)cancelAnimationFrame(micWaveRaf);micWaveRaf=null;if(micWaveStream){micWaveStream.getTracks().forEach(t=>t.stop());micWaveStream=null;}if(micWaveCtx){micWaveCtx.close();micWaveCtx=null;}}catch(e){}if(clear)drawWave(canvasEls(['voiceWaveCanvas','rightVoiceWaveCanvas']),0.02,0);}
function startSpeakWave(){try{if(speakWaveRaf)cancelAnimationFrame(speakWaveRaf);let phase=0;function tick(){drawWave(canvasEls(['novaSpeakWaveCanvas','rightSpeakWaveCanvas']),0.65+0.25*Math.sin(phase),phase);phase+=0.33;speakWaveRaf=requestAnimationFrame(tick);}tick();setNovaOrb('speaking','Nova speaking','Spoken reply is playing.');}catch(e){}}
