function voiceAudioConstraint(){const deviceId=selectedVoiceDeviceId();return {audio:deviceId?{deviceId:{exact:deviceId}}:true};}
async function refreshVoiceDeviceSelect(){const sel=document.getElementById('voiceDeviceSelect');if(!sel)return;const prior=selectedVoiceDeviceId();sel.innerHTML='<option value="">Default mic</option>';try{if(!navigator.mediaDevices||!navigator.mediaDevices.enumerateDevices){setVoiceDeviceStatus('Browser cannot enumerate microphones.');return;}const devices=await navigator.mediaDevices.enumerateDevices();const inputs=devices.filter(d=>d.kind==='audioinput');for(const d of inputs){const o=document.createElement('option');o.value=d.deviceId;o.textContent=d.label||('Microphone '+(sel.options.length));sel.appendChild(o);}sel.value=prior;setVoiceDeviceStatus(inputs.length?('Mics: '+inputs.length):'No microphone detected.');}catch(e){setVoiceDeviceStatus('Mic list unavailable: '+e);}}
async function diagnoseVoiceInput(){try{if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){setVoiceStatus('Microphone API not available in this browser. Use Chrome/Edge on localhost.');return false;}setVoiceStatus('Testing microphone permission/device...');const stream=await navigator.mediaDevices.getUserMedia(voiceAudioConstraint());stream.getTracks().forEach(t=>t.stop());setVoiceStatus('Microphone test passed.');await refreshVoiceDeviceSelect();return true;}catch(e){const name=e&&e.name?e.name:String(e);const extra=name==='OverconstrainedError'?' The selected microphone is unavailable; choose Default mic or refresh the mic list.':' Check Chrome site permissions and Windows input device.';setVoiceStatus('Microphone test failed: '+name+'.'+extra);return false;}}
function summariseForSpeech(text){
  let s=String(text||'');
  s=s.replace(/```[\s\S]*?```/g,' I have code output ready in the chat. ')
     .replace(/`[^`]*`/g,' code ')
     .replace(/https?:\/\/\S+/g,' link ')
     .replace(/^#{1,6}\s*/gm,'')
     .replace(/^[-*]\s+/gm,'')
     .replace(/[{}\[\]#*_>|]/g,' ')
     .replace(/\bPASS\b/g,'passed')
     .replace(/\bFAIL\b/g,'failed')
     .replace(/\s+/g,' ')
     .trim();
  if(!s)return '';
  const first=s.split(/(?<=[.!?])\s+/).slice(0,3).join(' ');
  return first.length>520?first.slice(0,520)+'…':first;
}
function conversationalVoiceSummary(text){
  const s=summariseForSpeech(text);
  if(!s)return '';
  if(/validation matrix passed|feature continuity audit passed|completed successfully/i.test(s))return 'Done. The checks passed, and I have left the details visible in the chat.';
  if(/completed with issues|failed|error/i.test(s))return 'I found an issue. I have shown the short summary first, with the technical details in the chat.';
  if(/Jarvis-style daemon endpoint is reachable/i.test(s))return 'Jarvis is reachable. The sidecar and higher authority controls are still gated.';
  return s;
}

function voiceAuthorized(){try{return !uiSettings.voiceAuthRequired || sessionStorage.getItem('wlaVoiceAuthorized')==='1' || localStorage.getItem('wlaVoiceRememberedAuth')==='1' || uiSettings.__voiceAuthorized===true;}catch(e){return !uiSettings.voiceAuthRequired;}}
function simpleVoiceHash(s){let h=2166136261;for(const ch of String(s||'')){h^=ch.charCodeAt(0);h=Math.imul(h,16777619);}return String(h>>>0);}
function renderVoiceAuth(){const p=document.getElementById('voiceAuthPanel'), st=document.getElementById('voiceAuthStatus');if(!p||!st)return;const locked=uiSettings.voiceAuthRequired&&!voiceAuthorized();p.classList.toggle('locked',locked);p.classList.toggle('unlocked',!locked);st.textContent=locked?'Locked: spoken commands will be transcribed but not sent until you unlock voice.':'Unlocked: spoken commands can be sent to chat.';}
function setVoicePassword(){const v=(document.getElementById('voicePasswordInput')?.value||'').trim();if(!v)return setVoiceStatus('Enter a voice password first.');try{localStorage.setItem('wlaVoicePasswordHash',simpleVoiceHash(v));document.getElementById('voicePasswordInput').value='';setVoiceStatus('Voice password saved locally in this browser.');}catch(e){setVoiceStatus('Could not save voice password: '+e);}renderVoiceAuth();}
function unlockVoiceSession(pass){const input=pass!==undefined?String(pass):(document.getElementById('voicePasswordInput')?.value||'');const saved=localStorage.getItem('wlaVoicePasswordHash')||'';if(saved&&simpleVoiceHash(input)!==saved){setVoiceStatus('Voice unlock failed.');renderVoiceAuth();return false;}try{sessionStorage.setItem('wlaVoiceAuthorized','1');if(uiSettings.voiceRememberLogin)localStorage.setItem('wlaVoiceRememberedAuth','1');uiSettings.__voiceAuthorized=true;setVoiceStatus('Voice commands unlocked.');}catch(e){}renderVoiceAuth();return true;}
