function voiceRequiresAuthNotice(text){const m=String(text||'').match(/(?:login|password|unlock)\s+(.+)$/i);if(m&&unlockVoiceSession(m[1].trim()))return true;const msg='Voice command held for login. Unlock voice in Settings, or say “Hey Nova login <password>”. Heard: '+String(text||'').slice(0,120);setNovaOrb('detected','Voice login required',msg);setVoiceStatus(msg);add('Assistant',msg+'\n\nI have not sent it to chat yet.');const input=document.getElementById('msg');if(input)input.value=String(text||'');return false;}
function populateSpeechVoices(){try{const sel=document.getElementById('speechVoiceSelect');if(!sel||!window.speechSynthesis)return;const chosen=localStorage.getItem('wlaSpeechVoiceURI')||'';const voices=window.speechSynthesis.getVoices()||[];sel.innerHTML='<option value="">Auto voice</option>'+voices.filter(v=>/^en/i.test(v.lang||'')||!v.lang).map(v=>'<option value="'+escAttr(v.voiceURI)+'">'+esc(v.name+' '+(v.lang||''))+'</option>').join('');sel.value=chosen;}catch(e){}}
function saveSpeechVoiceChoice(){try{localStorage.setItem('wlaSpeechVoiceURI',document.getElementById('speechVoiceSelect')?.value||'');}catch(e){}}
function selectedSpeechVoice(){try{const voices=window.speechSynthesis?.getVoices?.()||[];const uri=localStorage.getItem('wlaSpeechVoiceURI')||'';if(uri)return voices.find(v=>v.voiceURI===uri)||null;}catch(e){}return null;}
function testSpeechOutput(){avatarAudioActivated=true;uiSettings.audioMuted=false;uiSettings.audioEnabled=true;saveUiSettings();speakText('Nova voice output test. If you hear this, spoken replies are working.');}

function preferredSpeechVoice(){try{const direct=selectedSpeechVoice();if(direct)return direct;const voices=window.speechSynthesis?.getVoices?.()||[];if(uiSettings.voiceStyle==='default')return null;return voices.find(v=>/female|woman|zira|aria|jenny|samantha|susan|victoria|natasha|sonia/i.test(v.name+' '+v.voiceURI))||voices.find(v=>/^en/i.test(v.lang||''))||null;}catch(e){return null;}}
function speakText(text){try{if(!('speechSynthesis' in window)||uiSettings.audioMuted||isCurrentChatMuted())return;if(!avatarAudioActivated){return;}const u=new SpeechSynthesisUtterance(conversationalVoiceSummary(text));const v=preferredSpeechVoice();if(v)u.voice=v;u.pitch=Number(uiSettings.voicePitch||1.05);u.rate=Number(uiSettings.voiceRate||1.0);u.volume=Number(uiSettings.voiceVolume||0.9);u.onstart=()=>startSpeakWave();u.onend=()=>stopSpeakWave();u.onerror=()=>stopSpeakWave();window.speechSynthesis.cancel();window.speechSynthesis.speak(u);}catch(e){stopSpeakWave();}}
function stripEmojiForSpeech(text){return String(text||'').replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/gu,'').replace(/\s+/g,' ').trim();}
function maybeSpeakReply(reply, promptText){try{if(!avatarAudioEnabled||uiSettings.audioMuted||isCurrentChatMuted()||!avatarAudioActivated)return;const shouldSpeak=voiceModeOn()||wakeListening||!!uiSettings.autoSpeakVoiceMode;if(!shouldSpeak)return;const prompt=String(promptText||'').toLowerCase();if(prompt.startsWith('/activity')||prompt.startsWith('/llm-status')||prompt.startsWith('/files'))return;const spoken=stripEmojiForSpeech(conversationalVoiceSummary(reply));if(spoken)speakText(spoken);}catch(e){/* speech is optional and must never break chat delivery */}}

